import {pathPixelFootprintContract} from './path-pixel-footprint.js';
// Match the existing radiance integrator's local specular cone model.
export const transmittedSpreadGLSL='float hbRayTransmitSpread(float spread,float ratio,float inCosine,float outCosine){return min(1.57,spread*ratio*inCosine/max(.01,outCosine));}\n';
export const reflectedSpreadGLSL='float hbRayReflectSpread(float spread,float roughness){float r=max(.02,roughness);return min(1.57,spread+r*r*.5);}\n';
export const opticalSpreadContract=Object.freeze({version:1,pixelProjection:pathPixelFootprintContract,model:'local specular transmission spread; same ratio/cosine model, 0.01 grazing floor and 1.57 cap as the radiance integrator',inputs:'previous/current spread and selected base/coat roughness, each path IOR ratio, absolute incoming/outgoing shading-normal cosines',reflection:'non-glass base/coat proxy guide uses the selected lobe roughness and existing radiance heuristic min(1.57,spread+max(.02,roughness)^2/2); committed guide reuses its own live physical/coat evaluation',selection:'successful specular transmission uses eta/cosine; glass reflection/TIR retain spread; non-glass reflection broadens the local cone',resources:'existing current cone and previous spread scalars; no extra ray query, image, uniform, buffer or readback',remaining:'curved-normal differentials, full anisotropic/rough/participating-medium footprint transport'});
